'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var Int32Array = require( '@stdlib/array/int32' );
var dgttrf = require( '@stdlib/lapack/base/dgttrf' );
var Float64Array = require( '@stdlib/array/float64' );
var pkg = require( './../package.json' ).name;
var dgtts2 = require( './../lib/ndarray.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var opts = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} itrans - specifies the form of the system of equations
* @param {PositiveInteger} N - number of elements along each dimension
* @returns {Function} benchmark function
*/
function createBenchmark( order, itrans, N ) {
	var IPIV;
	var DU2;
	var sb1;
	var sb2;
	var DU;
	var DL;
	var B;
	var D;

	IPIV = new Int32Array( N );
	DU2 = new Float64Array( N-2 );
	DL = uniform( N-1, 100.0, 10000.0, opts );
	DU = uniform( N-1, 100.0, 10000.0, opts );
	D = uniform( N, 100.0, 1000000.0, opts );
	B = uniform( N*N, 0, 10000, opts );

	if ( isColumnMajor( order ) ) {
		sb1 = 1;
		sb2 = N;
	} else {
		sb1 = N;
		sb2 = 1;
	}

	dgttrf( N, DL, D, DU, DU2, IPIV );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dgtts2( itrans, N, N, DL, 1, 0, D, 1, 0, DU, 1, 0, DU2, 1, 0, IPIV, 1, 0, B, sb1, sb2, 0 ); // eslint-disable-line max-len
			if ( isnan( z[ i%z.length ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var itrans;
	var min;
	var max;
	var ord;
	var N;
	var f;
	var i;
	var k;

	min = 1; // 10^min
	max = 3; // 10^max

	for ( k = 0; k < LAYOUTS.length; k++ ) {
		ord = LAYOUTS[ k ];
		for ( itrans = 0; itrans < 3; itrans++ ) {
			for ( i = min; i <= max; i++ ) {
				N = pow( 10, i );
				f = createBenchmark( ord, itrans, N );
				bench( pkg+'::square_matrix:order='+ord+',itrans='+itrans+',size='+(N*N), f );
			}
		}
	}
}

main();
